/**
 * Bg-daemon idle-exit + binary-upgrade watchdog timers. Extracted from
 * bgDaemon.ts so the entry file stays under the 800-LOC budget. ant
 * 5170.js iFK:172-244 — these run for the lifetime of the daemon and
 * abort the AbortController when their condition fires.
 *
 * @dynamicRequire
 */

import { statSync } from 'node:fs'

import { logEvent } from '@thyrox/local-observability'

import type { WorkerVm } from './workerVm.js'

/**
 * idleActivityCount counts everything that pins the supervisor —
 * leases (active client connections), live workers, and detached
 * workers (still running but no longer supervised). Zero means the
 * daemon is idle and a transient origin can self-shutdown.
 */
export function makeIdleActivityCount(state: {
  leases: { readonly size: number }
  workers: { readonly size: number }
  detached: { readonly size: number }
}): () => number {
  return () => state.leases.size + state.workers.size + state.detached.size
}

export interface IdleExitOptions {
  origin: string
  abort: AbortController
  graceMs: number
  countActivity: () => number
}

/**
 * Set up the idle-exit watchdog. Returns a probe-tick callback caller
 * should fire every ~2s + a clear function to teardown. When the
 * activity count is 0 for `graceMs`, emits tengu_daemon_idle_exit and
 * aborts the controller (graceful shutdown).
 *
 * Service/shell origins pin the supervisor — they never idle-exit.
 */
export function setupIdleExitWatchdog(opts: IdleExitOptions): {
  probe: () => void
  dispose: () => void
} {
  let idleExitTimer: NodeJS.Timeout | null = null
  const probe = (): void => {
    if (opts.origin !== 'transient') return
    if (opts.abort.signal.aborted) return
    if (opts.countActivity() > 0) {
      if (idleExitTimer) {
        clearTimeout(idleExitTimer)
        idleExitTimer = null
      }
      return
    }
    if (idleExitTimer) return
    idleExitTimer = setTimeout(() => {
      idleExitTimer = null
      if (opts.abort.signal.aborted) return
      if (opts.countActivity() > 0) return
      logEvent('tengu_daemon_idle_exit', {
        grace_ms: String(opts.graceMs),
        cfg_workers: '0',
      })
      opts.abort.abort()
    }, opts.graceMs)
    idleExitTimer.unref()
  }
  return {
    probe,
    dispose() {
      if (idleExitTimer) {
        clearTimeout(idleExitTimer)
        idleExitTimer = null
      }
    },
  }
}

/**
 * Set up the binary-upgrade watchdog. Watches argv[1] (the ccb binary)
 * for mtime change; on detection, emits tengu_daemon_self_restart_on_upgrade
 * and aborts the controller so the wrapper / launchAgent restarts the
 * supervisor under the new binary. Bg workers are re-adopted from the
 * roster on the next supervisor's boot.
 *
 * Returns initial mtime + dispose function. If argv[1] is unreadable
 * (which happens on some compiled-bundle paths), returns initialMtime=null
 * and the probe is a no-op.
 */
export function setupUpgradeWatchdog(
  abort: AbortController,
): { dispose: () => void } {
  const binaryPath = process.argv[1] ?? process.execPath
  let initialMtime: number | null = null
  try {
    initialMtime = statSync(binaryPath).mtimeMs
  } catch {
    return { dispose: () => {} }
  }
  const timer = setInterval(() => {
    if (initialMtime === null) return
    if (abort.signal.aborted) return
    try {
      const current = statSync(binaryPath).mtimeMs
      if (current !== initialMtime) {
        logEvent('tengu_daemon_self_restart_on_upgrade', {
          old_mtime: String(initialMtime),
          new_mtime: String(current),
        })
        abort.abort()
      }
    } catch {
      // best-effort
    }
  }, 30_000)
  timer.unref()
  return {
    dispose() {
      clearInterval(timer)
    },
  }
}

/**
 * Worker map type for makeIdleActivityCount — exported so callers can
 * type-narrow without pulling WorkerVm into bgDaemonTimers.
 */
export type WorkerMaps = {
  workers: Map<string, WorkerVm>
  detached: Map<string, WorkerVm>
  leases: Set<unknown>
}

/**
 * Daemon socket path resolution.
 *
 * Mirrors ant 4138.js / 4137.js path layout, adapted for ccb's
 * vendor-prefix convention:
 *
 *   $TMPDIR/cc-daemon-<uid>/<repo-hash>/control.sock        rendezvous
 *   $TMPDIR/cc-daemon-<uid>/<repo-hash>/<short>.pty.sock    per-job PTY
 *   $TMPDIR/cc-daemon-<uid>/<repo-hash>/<short>.claim.sock  per-job claim
 *   ~/.claude/daemon/pty-pids/<short>.pid                   pid breadcrumbs
 *   ~/.claude/daemon/pty-pids/<short>.err                   crash breadcrumbs
 *
 * The repo-hash is sha256(realpath(cwd-at-start-of-time)) sliced to 8
 * hex chars. ant uses cwd to scope daemons to one cwd-tree at a time;
 * ccb keeps the same scoping so a `/repo-A` daemon doesn't try to
 * adopt `/repo-B` jobs.
 *
 * @dynamicRequire
 */

import { createHash } from 'node:crypto'
import { tmpdir } from 'node:os'
import { join, resolve } from 'node:path'

import { getConfigHomeDir } from '@thyrox/config/env/configHome.js'

/** Cached realpath-of-cwd hash for stability across sub-calls. */
let cachedRepoHash: string | undefined

function getTmpRoot(): string {
  // Termux has a non-/tmp default; respect it.
  const termuxPrefix = process.env.PREFIX
  if (process.env.TERMUX_VERSION && termuxPrefix) {
    return join(termuxPrefix, 'tmp')
  }
  return tmpdir() || '/tmp'
}

function getRepoHash(): string {
  if (cachedRepoHash) return cachedRepoHash
  cachedRepoHash = createHash('sha256')
    .update(resolve(process.cwd()))
    .digest('hex')
    .slice(0, 8)
  return cachedRepoHash
}

/** ant He() — `<tmp>/cc-daemon-<uid>/<repo-hash>` */
export function getDaemonScopeDir(): string {
  const uid = process.getuid?.() ?? 0
  return join(getTmpRoot(), `cc-daemon-${uid}`, getRepoHash())
}

/** ant oU() — control socket path. */
export function getControlSocketPath(): string {
  if (process.platform === 'win32') {
    // Windows uses a named pipe; ant has WV8('control'). For ccb we
    // mirror that name; full Windows daemon support is out of scope
    // for this iteration (Bun.Terminal availability + signal model
    // differs).
    return `\\\\.\\pipe\\ccb-control`
  }
  return join(getDaemonScopeDir(), 'control.sock')
}

/** PTY socket path for a given job short id. */
export function getPtySocketPath(short: string): string {
  return join(getDaemonScopeDir(), `${short}.pty.sock`)
}

/**
 * Rendezvous (control) socket path, given a job directory.
 *
 * ant runs TWO sockets per bg worker: the PTY socket carries screen
 * bytes (attach/replay), and a SEPARATE rendezvous socket carries the
 * out-of-band control channel (ant 4291.js worker-side server bound on
 * `THYROX_BG_RENDEZVOUS_SOCK`; ant 5016.js `naK` supervisor-side client).
 * ant's layout is `<scope>/rv/<short>.sock`; ccb keeps its existing flat
 * per-job-dir convention (the PTY socket is `<jobDir>/pty.sock` — see
 * `spawnPty.ts`), so the rendezvous socket sits alongside it as
 * `<jobDir>/rv.sock`.
 *
 * The rendezvous socket is what lets the INNER bg REPL push authoritative
 * `state` / `done` / `heartbeat` frames to the daemon supervisor without
 * round-tripping through disk. ccb previously had no such channel — the
 * inner REPL is sandboxed inside the PTY (stdout is screen bytes), so the
 * daemon could only infer liveness from PTY ctrl-frame heartbeats and guess
 * turn-outcome from a regex over assistant text (`useBgFleetStateSync`).
 */
export function getRendezvousSocketPath(jobDir: string): string {
  return join(jobDir, 'rv.sock')
}

/** Claim socket path (used by attach handshake). */
export function getClaimSocketPath(short: string): string {
  return join(getDaemonScopeDir(), `${short}.claim.sock`)
}

/**
 * `<getConfigHomeDir()>/daemon` directory for breadcrumb files. Unit tests
 * isolate by pointing `THYROX_CONFIG_DIR` at a tmpdir.
 */
export function getDaemonHomeDir(): string {
  return join(getConfigHomeDir(), 'daemon')
}

/** ~/.claude/daemon/pty-pids directory. */
export function getPtyPidsDir(): string {
  return join(getDaemonHomeDir(), 'pty-pids')
}
